# domain checks
if alpha <= lower_bound:
    return (False, None)
if not is_prime(alpha):
    return (False, None)
if math.gcd(p, q) != 1:
    return (False, None)
Lcalc = q // math.gcd(p, q)
if modulus != Lcalc:
    return (False, None)
if alpha % modulus != residue:
    return (False, None)
# consistency of k1, k2, k3 with the EV pattern
if k1 != 2 * alpha:
    return (False, None)
c = alpha * alpha + 2 * k1 - alpha - k2  # from k2 = (alpha^2 - c) + 2k1 - alpha
