# Count among i=2..alpha:
if Lcalc > 1:
    count_e = alpha // Lcalc
else:
    # if Lcalc == 1, every i is eligible, but we can only set a-3 of i>1 to distance zero
    count_e = alpha - 1
# We can choose at most (alpha-3) indices with i>1 to have d_i = 0; choose them among eligible to maximize
usable = min(count_e, alpha - 3)
num = usable + 1  # plus the free choice of |z_1| to be an integer modulus
den = alpha
# sanity: probability cannot exceed 1
if num > den:
    num = den
g = math.gcd(num, den)
numr = num // g
denr = den // g
if denr == 1:
    answer = f"### The final answer is: $\\boxed{{{numr}}}$"
else:
